def english_prompt(b, text):
    if all(ord(c) < 128 for c in text):
        return text
    try:
        T = b.types
        out = b.ask_gemini([T.Content(role="user", parts=[T.Part(text=text)])], deep=False, system=IMG_SYS)
        return (out or "").strip().strip('"')[:600] or text
    except Exception:
        return text


def sniff_image(data):
    """نوع الصورة من أول بايتات الملف (JPEG/PNG/WEBP/HEIC)."""
    if data[:3] == b"\xff\xd8\xff":
        return "image/jpeg"
    if data[:8] == b"\x89PNG\r\n\x1a\n":
        return "image/png"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "image/webp"
    if data[4:8] == b"ftyp" and data[8:12] in (b"heic", b"heix", b"heim", b"heis", b"mif1", b"msf1"):
        return "image/heic"
    return None


def img_models():
    """سلسلة موديلات رسم Gemini بالترتيب (الأقوى أول، قابل للتخصيص بـ GEMINI_IMAGE_MODEL)."""
    seen = []
    for m in [os.environ.get("GEMINI_IMAGE_MODEL", "").strip(),
              "gemini-3.1-flash-image-preview",
              "gemini-2.5-flash-image",
              "gemini-3-pro-image-preview"]:
        if m and m not in seen:
            seen.append(m)
    return seen


def _try_gemini_image(b, model, full):
    """محاولة واحدة: Interactions API الحديثة أولاً، وبعدها generate_content الكلاسيكية."""
    T = b.types
    client = b.client
    last = None
    try:
        if os.environ.get("IMAGE_USE_INTERACTIONS", "0") != "1":
            raise RuntimeError("interactions متوقفة")
        it = client.interactions.create(model=model, input=full)
        oi = getattr(it, "output_image", None)
        if oi is not None:
            data = getattr(oi, "data", None)
            if isinstance(data, str):
                try:
                    data = base64.b64decode(data, validate=True)
                except Exception:
                    data = data.encode("utf-8")
            if data:
                return data, (getattr(oi, "mime_type", None) or "image/png")
    except Exception as e:
        last = e
    cfg = None
    try:
        cfg = T.GenerateContentConfig(response_modalities=["IMAGE"],
                                      http_options=T.HttpOptions(timeout=45000))
    except Exception:
        try:
            cfg = T.GenerateContentConfig(response_modalities=["IMAGE"])
        except Exception:
            cfg = None
    resp = client.models.generate_content(model=model, contents=full, config=cfg)
    gen = getattr(resp, "generated_images", None) or []
    if gen:
        g = gen[0]
        im = getattr(g, "image", None) or g
        data = getattr(im, "image_bytes", None) or getattr(im, "_image_bytes", None)
        if not data:
            pil = getattr(im, "_pil_image", None)
            if pil is not None:
                buf = io.BytesIO()
                pil.save(buf, format="PNG")
                data = buf.getvalue()
        if data:
            return data, (getattr(im, "mime_type", None) or "image/png")
    for c in (getattr(resp, "candidates", None) or []):
        for p in (getattr(c.content, "parts", None) or []):
            inline = getattr(p, "inline_data", None)
            if inline is not None:
                return (getattr(inline, "data", None) or b""), (getattr(inline, "mime_type", None) or "image/png")
    if last is not None:
        raise last
    raise RuntimeError("الرد ما فيه صورة")


def gemini_image(b, full):
    """بيجرّب كل موديلات الرسم بالترتيب وبيرجّع (data, mime, model)."""
    last = None
    t0 = time.time()
    for model in img_models():
        if time.time() - t0 > 100:
            log.warning("الرسم: خلصت المهلة الكلية، وقفت التجربة")
            break
        try:
            log.info("الرسم: بجرّب %s", model)
            data, mime = _try_gemini_image(b, model, full)
            log.info("الرسم: %s خلص بـ %.0f ثانية", model, time.time() - t0)
            if data:
                return data, mime, model
        except Exception as e:
            last = e
            code = getattr(e, "code", None)
            if code in (401, 403, 429):
                raise
            log.warning("موديل الرسم %s فشل: %s", model, e)
    if last is not None:
        raise last
    raise RuntimeError("ما في موديل رسم متاح")


class _ImgError(Exception):
    """خطأ رسم برسالة عربية جاهزة للعرض للمستخدم."""


def img_label(model):
    """اسم قصير ومفهوم لموديل الرسم."""
    m = (model or "").lower()
    if "pollinations" in m:
        return "Pollinations"
    if "together" in m:
        return "Together FLUX"
    if "pro-image" in m:
        return "Nano Banana Pro"
    if "flash-image" in m or "nano" in m:
        return "Nano Banana"
    if "klein" in m:
        return "FLUX.2 klein"
    if "flux-2" in m:
        return "FLUX.2"
    if "lucid" in m:
        return "Lucid Origin"
    if "schnell" in m:
        return "FLUX.1 schnell"
    return (model or "").split("/")[-1]


_CHAT_NAMES = (("ryn mix", "Ryn mix"), ("gpt-oss", "GPT-OSS"), ("qwen", "Qwen"), ("deepseek", "DeepSeek"),
               ("kimi", "Kimi"), ("moonshot", "Kimi"), ("llama", "Llama"), ("gemma", "Gemma"),
               ("claude", "Claude"), ("gemini", "Gemini"))


def short_name(note, fallback="Gemini"):
    """بيحوّل ملاحظة البوت الطويلة لاسم الموديل بس."""
    n = (note or "").lower()
    if "جاوب gemini" in n or "استخدمت gemini" in n:
        return "Gemini"
    for k, v in _CHAT_NAMES:
        if k in n:
            return v
    return fallback


def _img_result(data, model_name, en):
    mime = sniff_image(data) or "image/jpeg"
    log.info("الرسم: %s · الوصف: %s", model_name, en[:200])
    return {"status": "done", "text": "تفضّل الصورة 🎨",
            "image": "data:%s;base64,%s" % (mime, base64.b64encode(data).decode()),
            "note": img_label(model_name)}


def pollinations_image(b, full, en):
    """احتياط مجاني (Pollinations). POLLINATIONS_MODEL ممكن يكون كذا موديل مفصولين بفاصلة، بيجرّبن بالترتيب.
    POLLINATIONS_KEY اختياري (مفتاح مجاني بيشيل العلامة المائية وبيرفع الحد)."""
    import random
    q = quote(full[:900], safe="")
    models = [m.strip() for m in os.environ.get("POLLINATIONS_MODEL", "flux").split(",") if m.strip()] or ["flux"]
    key = os.environ.get("POLLINATIONS_KEY", "").strip()
    last = "ما رد"
    for model in models:
        params = "model=%s&width=1024&height=1024&nologo=true&seed=%d" % (quote(model), random.randint(1, 999999))
        if key:
            params += "&key=" + quote(key, safe="")
        for base in ("https://gen.pollinations.ai/image/", "https://image.pollinations.ai/prompt/"):
            try:
                r = b.requests.get(base + q + "?" + params, timeout=90, headers={"User-Agent": "Mozilla/5.0"})
            except Exception as e:
                last = str(e)[:80]
                continue
            ct = str((getattr(r, "headers", None) or {}).get("content-type", ""))
            if r.status_code == 200 and ct.startswith("image/") and len(r.content) > 1000:
                return _img_result(r.content, "%s (Pollinations)" % model, en)
            last = "%s كود %s" % (model, r.status_code)
            log.warning("Pollinations %s %s: %s", base, model, last)
    raise _ImgError("Pollinations: " + last)


def together_image(b, full, en):
    """احتياط اختياري عبر Together AI (لازم TOGETHER_API_KEY)."""
    key = os.environ.get("TOGETHER_API_KEY", "").strip()
    model = os.environ.get("TOGETHER_IMAGE_MODEL", "black-forest-labs/FLUX.1-schnell-Free").strip()
