    def guard():
        """رد خطأ إذا مو مسموح، وإلا None."""
        if not authed():
            return jsonify(error="سجّل دخول"), 401
        if request.method == "POST" and request.headers.get("X-Requested-With") != "astra":
            return jsonify(error="طلب مرفوض"), 403
