    @app.post("/api/login")
    def api_login():
        if not users:
            return jsonify(error="WEB_PASSWORD أو WEB_USERS مو مضاف على Render"), 503
        if request.headers.get("X-Requested-With") != "astra":
            return jsonify(error="طلب مرفوض"), 403
        ip, now = client_ip(), time.time()
        recent = [t for t in fails.get(ip, []) if now - t < 600]
        if len(recent) >= 5:
            return jsonify(error="محاولات كتير، جرّب بعد 10 دقايق"), 429
        given = str((request.get_json(silent=True) or {}).get("password", "")).strip()
        who = None
        for n, pw in users.items():
            if hmac.compare_digest(given.encode(), pw.encode()):
                who = n
        if who:
            fails.pop(ip, None)
            session.clear()
            session["ok"] = True
            session["u"] = who
            session.permanent = True
            return jsonify(ok=True)
        recent.append(now)
        fails[ip] = recent
        time.sleep(0.8)  # يبطّئ التخمين
        return jsonify(error="كلمة السر غلط"), 401

    @app.post("/api/logout")
    def api_logout():
        session.clear()
        return jsonify(ok=True)

    # ---------- الدردشة (بشكل مهمة + polling حتى ما ينقطع الطلب الطويل) ----------
    def clean_history(raw):
        out = []
        for m in (raw if isinstance(raw, list) else [])[-20:]:
            if not isinstance(m, dict):
                continue
            role = "model" if m.get("role") == "model" else "user"
            text = str(m.get("text", ""))[:150000]
            if text.strip():
                out.append((role, text))
        while len(out) > 1 and sum(len(t) for _, t in out) > 450000:   # ميزانية السياق: بنشيل الأقدم
            out.pop(0)
        while out and out[0][0] != "user":
            out.pop(0)
        return out

    def build_memory_prompt(raw):
        if not isinstance(raw, dict) or not raw.get("enabled", True):
            return ""
        name = str(raw.get("name") or "").strip()[:120]
        custom = str(raw.get("custom") or "").strip()[:2000]
        facts = [str(x).strip()[:400] for x in (raw.get("facts") or [])[:60] if str(x).strip()]
        lines = []
        if name:
            lines.append("• اسم المستخدم: " + name)
        if custom:
            lines.append("• تخصيص وتفضيلات المستخدم:\n" + custom)
        if facts:
            lines.append("• ذكريات ومعلومات محفوظة على هاتف المستخدم:\n" + "\n".join("  - " + f for f in facts))
        mem_block = "\n".join(lines) if lines else "(لا توجد معلومات مسبقة بعد)"
        return (
            "[ملف التخصيص والذاكرة من هاتف المستخدم]\n"
            + mem_block
            + "\n(ملاحظة للنظام: راعِ تفضيلات المستخدم ومعلوماته أعلاه بشكل طبيعي في ردك. "
            "وإذا طلب منك المستخدم تذكّر أو حفظ معلومة جديدة عنه للمستقبل مثل «تذكر أني...» أو «احفظ عندك...»، "
            "أضف في آخر ردك السطر التالي بالضبط: [[MEM: المعلومة باختصار]] ليتم حفظها تلقائياً في ملف هاتفه.)\n---\n"
        )

    MOOD_RE = re.compile(r"\[\[MOOD:\s*(upset|happy|ok|sad|worried|excited|touched)\s*(?::\s*(.+?))?\s*\]\]", re.S)

    def set_progress(job_id, t):
        with jlock:
            j = jobs.get(job_id)
            if j and j.get("status") == "running":
                j["progress"] = str(t)[:80]

    def run_job(job_id, text, history, mem_prompt="", emo=False, u="main", net=False):
        try:
            T = b.types
            W = wid(u)
            mood = md(u)
            if emo and mood["state"] == "upset":
                if time.time() - mood["since"] > 600:   # بيسامح لحاله بعد 10 دقايق
                    mood.update(state="normal", reason="", since=0.0)
                else:
                    mem_prompt = UPSET_PROMPT % (mood["reason"] or "تصرّف ما عجبه") + mem_prompt
            contents = [T.Content(role=r, parts=[T.Part(text=t)]) for r, t in history]
            if emo and mood["state"] != "upset" and mood.get("feel") and time.time() - mood.get("feel_since", 0) < 1200:
                mem_prompt = FEEL_HINT % (FEEL_AR.get(mood["feel"], ""), (" بسبب: " + mood["feel_why"]) if mood.get("feel_why") else "") + mem_prompt
            pctx = page_context(b, text) if len(text) < 3000 else ""
            if pctx:
                mem_prompt = pctx + mem_prompt
            fix_intent = bool(_FIX_RE.search(text))
            fix_orig = None
            if fix_intent:   # فحص آلي لكود الرسالة وللملفات المرفقة
                blocks_in = extract_blocks(text)
                if not blocks_in:
                    lc = loose_code(text)
                    blocks_in = [("", lc[1])] if lc else []
                items = [("بلوك %d" % i, guess_lang(lg, cd), cd) for i, (lg, cd) in enumerate(blocks_in, 1)]
                if len(items) == 1 and items[0][1]:
                    fix_orig = (items[0][1], items[0][2])
                items += doc_code_items(b.get_doc(W))
                if items:
                    mem_prompt = CODEFIX_RULES + FIX_RULES + diagnose(items) + numbered_listing(items) + mem_prompt
            full_user_text = (mem_prompt + text) if mem_prompt else text
            ctx = b.get_doc(W)
            if ctx:
                base = ctx["alt"] if ctx.get("alt") else ctx["parts"]
                parts = list(base) + [T.Part(text=full_user_text)]
            else:
                parts = [T.Part(text=full_user_text)]
            contents.append(T.Content(role="user", parts=parts))
            deep = b.is_deep_question(text)
            big = contents_size(contents) > BIG_CHARS
            is_mix_mode = bool(wm(u)["mix"])
            code_req = (is_mix_engineering_request(text, ctx) if is_mix_mode else (fix_intent or b.is_code_request(text)))
            answer = note = None
            kind = ""
            mix_meta = {}
            yt = [m.group(0) for m in YT_RE.finditer(text)]
            net_fail = ""
            if not net and not is_mix_mode and b.client and len(text) < 1500 and "```" not in text:
                net = needs_web(text)
            if (net or yt) and b.client:
                try:
                    answer, note = web_answer(b, contents, net, yt)
                    kind = "clean"
                except Exception as e:
                    log.warning("البحث/الفيديو فشل: %s", redact_secrets(str(e)[:200]))
                    answer = None
                    net_fail = " (الإنترنت ما اشتغل هلق، جاوبت من معلوماتي)"
            if not answer and is_mix_mode and b._text_only(contents):
                answer, note = mix_answer(b, contents, mix_members(code_req), code=code_req, fix=fix_intent,
                                         progress=lambda t: set_progress(job_id, t), meta=mix_meta)
                kind = "clean"
            if not answer and big and b.client:   # مدخل كبير خارج وضع Ryn mix (أو كاحتياط): Gemini بسياقو الكبير
                try:
                    answer = big_gemini(b, contents, BIG_HINT)
                    note, kind = "Gemini", "clean"
                except Exception as e:
                    log.warning("big_gemini فشل: %s", redact_secrets(str(e)[:200]))
                    answer = None
            if answer:
                pass
            else:
                answer, note = b.ask_model(W, contents, deep=deep, code=b.is_code_request(text))
            if net_fail:
                log.info("الإنترنت ما اشتغل، جاوب من معلوماته")
            plain = (kind != "clean") and not note   # جواب عادي بدون أي توجيه خاص
            if kind != "clean":
                sel = b.chat_provider.get(W, "gemini")
                labels = {o["id"]: o["label"] for o in build_options()}
                note = short_name(note, labels.get(sel, "Gemini"))
            if net_fail:
                note = note + " · ⚠️ بدون إنترنت"
            verified = None
            if answer and (code_req or big or "```" in answer):
                call = (lambda m: big_gemini(b, m, BIG_HINT)) if (big and b.client) else \
                       (lambda m: b.ask_model(W, m, deep=False, code=True)[0])
                answer = continue_if_cut(b, answer, contents, call)   # كمّل إذا انقطع بنص كود
                if code_req:
                    answer, verified = verify_code(b, answer, contents, call)
                if fix_orig and answer:
                    answer = add_diff(answer, fix_orig[0], fix_orig[1])
            if verified is True:
                note = note + " · ✅ مفحوص"
            elif verified is False:
                note = note + " · ⚠️ فيه خطأ ما انحلّ"
            if is_cancelled(job_id):
                return
            if emo and answer:
                mm = MOOD_RE.search(answer)
                if mm:
                    kind, why = mm.group(1), (mm.group(2) or "").strip()[:120]
                    answer = MOOD_RE.sub("", answer).strip()
                    if kind == "upset":
                        if mood["state"] != "upset":
                            mood.update(state="upset", reason=why, since=time.time())
                        note = (note + " · 😤 زعلان منك").strip()
                    elif kind == "ok":
                        mood.update(state="normal", reason="", since=0.0)
                        mood.pop("feel", None)
                        note = (note + " · 😊 رجع مبسوط").strip()
                    else:
                        note = (note + " · " + FEEL_NOTE[kind]).strip()
                        if kind in ("sad", "worried"):   # بيضل متعاطف لحد ما يتحسّن
                            mood.update(feel=kind, feel_why=why, feel_since=time.time())
                        else:
                            mood.pop("feel", None)
            new_mems = [m.strip()[:300] for m in re.findall(r"\[\[MEM:\s*(.+?)\s*\]\]", answer or "") if m.strip()]
            if new_mems:
                answer = re.sub(r"\[\[MEM:\s*.+?\s*\]\]", "", answer or "").strip()
            if deep and answer and len(answer) > 150 and b.load_knowledge() and plain:
                answer = b.review_answer(W, text, answer)
                answer = re.sub(r"\[\[MEM:\s*.+?\s*\]\]", "", answer or "").strip()
            dl = None
            fext = filegen.detect_file_request(text) if filegen else None
            asked_file = bool(fext)
            if fext in _FILEGEN_BYPASS and answer and extract_blocks(answer):
                fext = None   # الكود بينحمّل من بلوكاتو حرفياً (filegen بيشيل __ و` وبياخد أول بلوك بس)
            if fext and answer:
                try:
                    fname, mime, data = filegen.make_file(fext, answer, text)
                    fid = store_file(fname, mime, data)
                    dl = {"id": fid, "name": fname, "ext": fext, "size": len(data)}
                    log.info("ملف تحميل جاهز: %s (%s، %d بايت)", fname, fext, len(data))
                except Exception:
                    log.exception("توليد ملف التحميل فشل")
            files_out = [dl] if dl else []
            if not dl and answer:
                try:
                    fc = mix_meta.get("final_code")
                    if fc and fc in answer:   # Ryn mix للكود: ملف دايماً للكود النهائي (حتى لو قصير)
                        files_out = auto_code_files(fc, text, fix_intent, min_lines=1)
                    else:
                        files_out = auto_code_files(answer, text, fix_intent, min_lines=(1 if asked_file else 12))
                except Exception:
                    log.exception("توليد ملفات الكود التلقائية فشل")
            res = {"status": "done", "text": answer or "", "note": note or "", "memories": new_mems,
                   "file": (files_out[0] if files_out else None), "files": files_out}
        except Exception as e:
            log.exception("web chat error")
            msg = b.friendly_error(e)
            if getattr(e, "code", None) == 402:
                msg = "💳 رصيد OpenRouter ما بيكفي لهالموديل (مدفوع). اشحن رصيد أو اختار موديل تاني."
            res = {"status": "error", "text": msg}
        finish(job_id, res)

    @app.post("/api/chat")
    def api_chat():
        bad = guard()
        if bad:
            return bad
        data = request.get_json(silent=True) or {}
        text = str(data.get("message", "")).strip()
        if not text:
            return jsonify(error="الرسالة فاضية"), 400
        mem_prompt = build_memory_prompt(data.get("memory"))
        emo_on = data.get("emo") is True
        if emo_on:
            mem_prompt = EMO_PROMPT + mem_prompt
        else:
            md().update(state="normal", reason="", since=0.0)
        now = time.time()
        with jlock:
            for k in [k for k, v in jobs.items() if now - v["ts"] > 900]:
                jobs.pop(k, None)
            if sum(1 for v in jobs.values() if v["status"] == "running" and v.get("uid") == uid()) >= 2:
                return jsonify(error="في طلبين شغّالين، استنى لحظة"), 429
            job_id = uuid.uuid4().hex
            jobs[job_id] = {"status": "running", "ts": now, "uid": uid()}
        threading.Thread(target=run_job, args=(job_id, text[:400000], clean_history(data.get("history")), mem_prompt, emo_on, uid()),
                         daemon=True).start()
        return jsonify(job=job_id)

    @app.get("/api/job/<job_id>")
    def api_job(job_id):
        bad = guard()
        if bad:
            return bad
        with jlock:
            j = jobs.get(job_id)
            if not j or j.get("uid") != uid():
                return jsonify(status="error", text="انتهت صلاحية الطلب، جرّب تاني."), 404
            return jsonify({k: v for k, v in j.items() if k not in ("ts", "uid")})

    # ---------- الملفات ----------
    @app.post("/api/upload")
    def api_upload():
        bad = guard()
        if bad:
            return bad
        fl = [f for f in request.files.getlist("file") if f and f.filename][:10]
        if not fl:
            return jsonify(error="ما وصل ملف"), 400
        T = b.types
        all_parts, alt_parts, names, skipped = [], [], [], []
        any_alt = any_img = trunc = False
        n_img = 0
        reasons = {"unsupported": "نوع الملف مو مدعوم", "empty": "فاضي أو ما قدرت أقرأ نصه",
                   "bad_zip": "ملف zip تالف", "zip_big": "zip كبير كتير"}
        first_err = ""
        multi = len(fl) > 1
        for idx, f in enumerate(fl, 1):
            data = f.read()
            name = os.path.basename(f.filename) or "file"
            if len(data) > MAX_UPLOAD:
                skipped.append(name + " (أكبر من 30 ميجا)")
                continue
            alt = None
            try:
                mime = sniff_image(data)
                low = name.lower()
                if mime:   # صورة: بنعرفها من محتواها، مو من اسمها
                    parts = [T.Part.from_bytes(data=data, mime_type=mime)]
                    any_img = True
                    n_img += 1
                elif low.endswith(".zip"):
                    parts, tr = zip_parts(T, name, data)
                    trunc |= tr
                elif low.endswith((".pdf", ".docx")) or os.path.splitext(low)[1] in getattr(b, "MIME_BY_EXT", {}):
                    parts = b.build_doc_parts(name, data)
                    alt = b.pdf_alt_parts(name, data) if low.endswith(".pdf") else None
                else:
                    parts, tr = text_file_parts(T, name, data)
                    trunc |= tr
            except ValueError as e:
                msg = reasons.get(str(e), "ما قدرت أفتحو، يمكن تالف")
                first_err = first_err or msg
                skipped.append("%s (%s)" % (name, msg))
                continue
            label = [T.Part(text="[مرفق %d: %s]" % (len(names) + 1, name))] if multi else []
            all_parts += label + parts
            alt_parts += label + (alt or parts)
            any_alt |= bool(alt)
            names.append(name)
        if not names:
            return jsonify(error=first_err or "ما قدرت أقرأ الملفات"), 400
        docname = names[0] if len(names) == 1 else "%d ملفات: %s%s" % (len(names), "، ".join(names[:3]), "…" if len(names) > 3 else "")
        b.set_doc(wid(), docname, all_parts, alt_parts if any_alt else None)
        if any_img:
            b.doc_ctx[wid()]["image"] = True
            b.doc_ctx[wid()]["exp"] = time.time() + 600   # لو في صور: بتضل مرفقة 10 دقايق
        return jsonify(ok=True, name=docname, image=(n_img == len(names)), count=len(names),
                       skipped=skipped, truncated=trunc)

    # ---------- تفريغ الصوت (تسجيل من الميكروفون) ----------
    @app.post("/api/transcribe")
    def api_transcribe():
        bad = guard()
        if bad:
            return bad
        f = request.files.get("audio")
        data = f.read() if f else b""
        if len(data) < 1000:
            return jsonify(error="التسجيل قصير أو فاضي"), 400
        if len(data) > 20 * 1024 * 1024:
            return jsonify(error="التسجيل كبير كتير"), 413
        mime = (f.mimetype or "audio/webm").split(";")[0].strip() or "audio/webm"
        ext = {"audio/webm": "webm", "audio/ogg": "ogg", "audio/mp4": "m4a", "audio/mpeg": "mp3", "audio/wav": "wav",
               "audio/x-m4a": "m4a"}.get(mime, "webm")
        text, why = "", ""
        if b._groq_ready():   # Whisper عبر Groq (بيقبل webm/mp4/ogg)
            try:
                form = {"model": os.environ.get("GROQ_STT_MODEL", "whisper-large-v3-turbo"), "response_format": "json",
                        "prompt": "تفريغ كلام عربي شامي مع مصطلحات برمجة بالإنجليزي مثل Python وJavaScript وAPI."}
                lang = os.environ.get("STT_LANGUAGE", "").strip()
                if lang:
                    form["language"] = lang
                r = b.requests.post(b.GROQ_BASE + "/audio/transcriptions",
                                    headers={"Authorization": "Bearer " + b._env_key("GROQ_API_KEY")},
                                    files={"file": ("voice." + ext, data, mime)}, data=form, timeout=60)
                if r.status_code == 200:
                    text = str((r.json() or {}).get("text", "")).strip()
                else:
                    why = "Groq %s" % r.status_code
            except Exception as e:
                why = "Groq: " + str(e)[:80]
        if not text and b.client:   # احتياط: Gemini بيسمع الصوت
            try:
                T = b.types
                resp = b.client.models.generate_content(
                    model=[m for m in b.FAST_MODELS if isinstance(m, str)][0],
                    contents=[T.Content(role="user", parts=[
                        T.Part.from_bytes(data=data, mime_type=mime),
                        T.Part(text="فرّغ هالتسجيل الصوتي حرفياً بلغة المتحدث، بدون أي إضافة أو شرح.")])],
                    config=T.GenerateContentConfig(http_options=T.HttpOptions(timeout=60000)))
                text = (resp.text or "").strip()
            except Exception as e:
                why = (why + " | " if why else "") + "Gemini: " + str(e)[:80]
        if not text:
            log.warning("تفريغ الصوت فشل: %s", why)
            return jsonify(error="ما قدرت أفرّغ الصوت. جرّب تحكي أوضح أو أطول شوي."), 502
        return jsonify(ok=True, text=text)

